
import { useState } from 'react';
import { VehicleModel } from '../../../mocks/vehicleSelect';
import { bodyTypes } from '../../../mocks/vehicleSelect';

interface ModelListProps {
  models: VehicleModel[];
  makerName: string;
  selectedModelId: string | null;
  onSelect: (id: string) => void;
  onClearMaker: () => void;
}

export default function ModelList({
  models,
  makerName,
  selectedModelId,
  onSelect,
  onClearMaker,
}: ModelListProps) {
  const [bodyFilter, setBodyFilter] = useState('すべて');
  const [sortBy, setSortBy] = useState<'popular' | 'name'>('popular');

  // Filter models by selected body type
  const filtered = models.filter(
    (m) => bodyFilter === 'すべて' || m.bodyType === bodyFilter,
  );

  // Sort the filtered list
  const sorted = [...filtered].sort((a, b) => {
    if (sortBy === 'popular') return b.partCount - a.partCount;
    return a.name.localeCompare(b.name, 'ja');
  });

  // Determine which body‑type buttons should be shown
  const availableBodyTypes = bodyTypes.filter(
    (bt) => bt === 'すべて' || models.some((m) => m.bodyType === bt),
  );

  return (
    <section className="mt-8">
      <div className="flex items-center gap-3 mb-5">
        <span className="bg-red-600 text-white text-xs font-bold px-3 py-1 rounded whitespace-nowrap">
          STEP 2
        </span>
        <h2 className="text-xl font-bold text-gray-800">
          車種を選択してください
        </h2>
      </div>

      <div className="flex items-center gap-2 mb-4">
        <span className="bg-red-100 text-red-700 text-sm font-bold px-3 py-1.5 rounded flex items-center gap-2 whitespace-nowrap">
          <i className="ri-checkbox-circle-fill w-4 h-4 flex items-center justify-center"></i>
          {makerName}
        </span>
        <button
          onClick={onClearMaker}
          className="text-xs text-gray-500 hover:text-red-600 cursor-pointer flex items-center gap-1 whitespace-nowrap"
        >
          <i className="ri-close-circle-line w-4 h-4 flex items-center justify-center"></i>
          メーカーを変更
        </button>
      </div>

      <div className="flex items-center justify-between mb-4">
        <div className="flex gap-2 flex-wrap">
          {availableBodyTypes.map((bt) => (
            <button
              key={bt}
              onClick={() => setBodyFilter(bt)}
              className={`px-3 py-1.5 rounded text-sm font-bold cursor-pointer transition-colors whitespace-nowrap ${
                bodyFilter === bt
                  ? 'bg-red-600 text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {bt}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-1 bg-gray-100 rounded p-1">
          <button
            onClick={() => setSortBy('popular')}
            className={`px-3 py-1 rounded text-xs font-bold cursor-pointer transition-colors whitespace-nowrap ${
              sortBy === 'popular' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500'
            }`}
          >
            人気順
          </button>
          <button
            onClick={() => setSortBy('name')}
            className={`px-3 py-1 rounded text-xs font-bold cursor-pointer transition-colors whitespace-nowrap ${
              sortBy === 'name' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500'
            }`}
          >
            五十音順
          </button>
        </div>
      </div>

      {sorted.length === 0 ? (
        <div className="bg-gray-50 border border-gray-200 rounded-lg p-8 text-center">
          <i className="ri-car-line text-4xl text-gray-300 mb-2"></i>
          <p className="text-sm text-gray-500">該当する車種が見つかりません</p>
        </div>
      ) : (
        <div className="grid grid-cols-4 gap-4">
          {sorted.map((model) => (
            <button
              key={model.id}
              onClick={() => onSelect(model.id)}
              className={`bg-white border-2 rounded-lg overflow-hidden cursor-pointer transition-all hover:shadow-lg text-left ${
                selectedModelId === model.id
                  ? 'border-red-500 shadow-md'
                  : 'border-gray-200 hover:border-red-400'
              }`}
            >
              <div className="w-full h-36 bg-gray-100 overflow-hidden">
                <img
                  src={model.image}
                  alt={model.name}
                  className="w-full h-full object-cover object-top"
                />
              </div>
              <div className="p-3">
                <div className="flex items-center justify-between mb-1">
                  <h3 className="text-sm font-bold text-gray-800">{model.name}</h3>
                  {selectedModelId === model.id && (
                    <div className="w-5 h-5 flex items-center justify-center bg-red-600 rounded-full flex-shrink-0">
                      <i className="ri-check-line text-white text-xs"></i>
                    </div>
                  )}
                </div>
                <p className="text-xs text-gray-500 mb-1.5">{model.yearRange}</p>
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded whitespace-nowrap">
                    {model.bodyType}
                  </span>
                  {model.engineTypes.map((e) => (
                    <span
                      key={e}
                      className="text-xs bg-green-50 text-green-700 px-2 py-0.5 rounded whitespace-nowrap"
                    >
                      {e}
                    </span>
                  ))}
                </div>
                <p className="text-xs text-red-600 font-bold mt-2">
                  {model.partCount.toLocaleString()}点の対応パーツ
                </p>
              </div>
            </button>
          ))}
        </div>
      )}
    </section>
  );
}
