
import { VehicleMaker } from '../../../mocks/vehicleSelect';

interface MakerGridProps {
  makers: VehicleMaker[];
  selectedMakerId: string | null;
  onSelect: (id: string) => void;
}

export default function MakerGrid({
  makers,
  selectedMakerId,
  onSelect,
}: MakerGridProps) {
  return (
    <section>
      <div className="flex items-center gap-3 mb-5">
        <span className="bg-red-600 text-white text-xs font-bold px-3 py-1 rounded whitespace-nowrap">
          STEP 1
        </span>
        <h2 className="text-xl font-bold text-gray-800">
          メーカーを選択してください
        </h2>
      </div>

      <div className="grid grid-cols-5 gap-4">
        {makers.map((maker) => (
          <button
            key={maker.id}
            onClick={() => onSelect(maker.id)}
            className={`bg-white border-2 rounded-lg p-4 flex flex-col items-center gap-2 cursor-pointer transition-all hover:shadow-lg whitespace-nowrap ${
              selectedMakerId === maker.id
                ? 'border-red-500 shadow-md bg-red-50'
                : 'border-gray-200 hover:border-red-400'
            }`}
            type="button"
          >
            <div className="w-full h-16 flex items-center justify-center overflow-hidden">
              <img
                src={maker.image}
                alt={maker.nameEn}
                className="max-w-full max-h-full object-contain"
              />
            </div>

            <span className="text-sm font-bold text-gray-800">{maker.name}</span>

            <div className="flex items-center gap-1 text-xs text-gray-500">
              <span>{maker.modelCount}車種</span>
              <span>・</span>
              <span>{maker.partCount.toLocaleString()}点</span>
            </div>

            {selectedMakerId === maker.id && (
              <div className="w-5 h-5 flex items-center justify-center bg-red-600 rounded-full">
                <i className="ri-check-line text-white text-xs"></i>
              </div>
            )}
          </button>
        ))}
      </div>
    </section>
  );
}
