
import { useState } from 'react';
import { Link } from 'react-router-dom';
import { VehicleProduct, productCategories } from '../../../mocks/vehicleSelect';

interface CompatibleProductsProps {
  products: VehicleProduct[];
  makerName: string;
  modelName: string;
}

/**
 * CompatibleProducts
 *
 * Renders a list of products that are compatible with a given vehicle.
 * The component supports filtering by category and sorting by a few
 * predefined criteria. All UI elements are defensive – they gracefully
 * handle missing data (e.g. missing images, tags, prices) and never
 * cause a runtime exception.
 */
export default function CompatibleProducts({
  products,
  makerName,
  modelName,
}: CompatibleProductsProps) {
  const [categoryFilter, setCategoryFilter] = useState('すべて');
  const [sortBy, setSortBy] = useState('popular');

  // -----------------------------------------------------------------
  // 1️⃣  Defensive filtering – guard against undefined values.
  // -----------------------------------------------------------------
  const filtered = (products ?? []).filter((p) => {
    if (!p) return false;
    return categoryFilter === 'すべて' || p.category === categoryFilter;
  });

  // -----------------------------------------------------------------
  // 2️⃣  Defensive sorting – ensure the fields we compare exist.
  // -----------------------------------------------------------------
  const sorted = [...filtered].sort((a, b) => {
    // Fallback values if any field is missing
    const priceA = a.price ?? 0;
    const priceB = b.price ?? 0;
    const ratingA = a.rating ?? 0;
    const ratingB = b.rating ?? 0;
    const reviewA = a.reviewCount ?? 0;
    const reviewB = b.reviewCount ?? 0;

    if (sortBy === 'price-asc') return priceA - priceB;
    if (sortBy === 'price-desc') return priceB - priceA;
    if (sortBy === 'rating') return ratingB - ratingA;
    // default = popular (review count)
    return reviewB - reviewA;
  });

  // -----------------------------------------------------------------
  // 3️⃣  Helper to safely render an image.
  // -----------------------------------------------------------------
  const renderImage = (src: string | undefined, alt: string) => {
    const placeholder =
      'data:image/svg+xml;charset=UTF-8,<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300"><rect width="100%" height="100%" fill="%23f3f4f6"/><text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle" fill="%23999" font-size="20">No image</text></svg>';
    return (
      <img
        src={src ?? placeholder}
        alt={alt}
        className="w-full h-full object-cover object-top group-hover:scale-105 transition-transform duration-300"
        onError={(e) => {
          const target = e.currentTarget as HTMLImageElement;
          target.src = placeholder;
        }}
      />
    );
  };

  return (
    <section className="mt-8">
      {/* Header */}
      <div className="flex items-center gap-3 mb-5">
        <span className="bg-red-600 text-white text-xs font-bold px-3 py-1 rounded whitespace-nowrap">
          STEP 3
        </span>
        <h2 className="text-xl font-bold text-gray-800">
          {makerName} {modelName} の対応パーツ
        </h2>
        <span className="text-sm text-gray-500">（{products?.length ?? 0}件）</span>
      </div>

      {/* Controls */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex gap-2 flex-wrap">
          {productCategories.map((cat) => (
            <button
              key={cat}
              type="button"
              onClick={() => setCategoryFilter(cat)}
              className={`px-3 py-1.5 rounded text-sm font-bold cursor-pointer transition-colors whitespace-nowrap ${
                categoryFilter === cat
                  ? 'bg-red-600 text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        <select
          value={sortBy}
          onChange={(e) => setSortBy(e.target.value)}
          className="border border-gray-300 rounded px-3 py-1.5 text-sm cursor-pointer focus:outline-none focus:border-red-500"
        >
          <option value="popular">人気順</option>
          <option value="price-asc">価格が安い順</option>
          <option value="price-desc">価格が高い順</option>
          <option value="rating">評価順</option>
        </select>
      </div>

      {/* No results */}
      {sorted.length === 0 ? (
        <div className="bg-gray-50 border border-gray-200 rounded-lg p-8 text-center">
          <i className="ri-box-3-line text-4xl text-gray-300 mb-2" />
          <p className="text-sm text-gray-500">該当するパーツが見つかりません</p>
        </div>
      ) : (
        // Product grid
        <div className="grid grid-cols-4 gap-4" data-product-shop>
          {sorted.map((product) => (
            <Link
              to={`/product/${product.id}`}
              key={product.id}
              className="bg-white border border-gray-200 rounded-lg overflow-hidden hover:shadow-lg transition-shadow cursor-pointer group"
            >
              {/* Image + tags */}
              <div className="relative w-full h-48 bg-gray-50 overflow-hidden">
                {renderImage(product.image, product.name)}
                {/* Tags */}
                <div className="absolute top-2 left-2 flex gap-1 flex-wrap">
                  {(product.tags ?? []).map((tag, idx) => (
                    <span
                      key={idx}
                      className={`text-xs px-2 py-0.5 rounded whitespace-nowrap ${
                        tag === '在庫有り'
                          ? 'bg-green-500 text-white'
                          : tag === 'NEW'
                          ? 'bg-red-500 text-white'
                          : tag === '送料無料'
                          ? 'bg-teal-500 text-white'
                          : tag === 'SALE'
                          ? 'bg-orange-500 text-white'
                          : tag === '人気'
                          ? 'bg-yellow-500 text-white'
                          : 'bg-gray-500 text-white'
                      }`}
                    >
                      {tag}
                    </span>
                  ))}
                </div>

                {/* Discount badge */}
                {product.discount && (
                  <div className="absolute top-2 right-2">
                    <span className="bg-red-600 text-white text-xs px-2 py-0.5 rounded font-bold whitespace-nowrap">
                      {product.discount}
                    </span>
                  </div>
                )}
              </div>

              {/* Details */}
              <div className="p-3">
                <p className="text-xs text-gray-500 mb-1">{product.brand}</p>
                <h3 className="text-sm font-bold text-gray-800 mb-1.5 line-clamp-2 h-10 leading-5">
                  {product.name}
                </h3>
                <p className="text-xs text-teal-600 mb-2 flex items-center gap-1">
                  <i className="ri-car-line w-3 h-3 flex items-center justify-center" />
                  {product.compatibility}
                </p>

                {/* Rating */}
                <div className="flex items-center gap-1 mb-2">
                  <div className="flex text-yellow-500 text-xs">
                    {[...Array(5)].map((_, i) => (
                      <i
                        key={i}
                        className={i < Math.round(product.rating ?? 0) ? 'ri-star-fill' : 'ri-star-line'}
                      />
                    ))}
                  </div>
                  <span className="text-xs text-gray-400">
                    ({product.reviewCount ?? 0})
                  </span>
                </div>

                {/* Price & points */}
                <div className="flex items-end justify-between">
                  <div>
                    {product.originalPrice && (
                      <p className="text-xs text-gray-400 line-through">
                        ¥{product.originalPrice.toLocaleString()}
                      </p>
                    )}
                    <p className="text-lg font-bold text-red-600">
                      ¥{product.price?.toLocaleString() ?? '-'}
                    </p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-gray-400">税込</p>
                    <p className="text-xs text-orange-600 font-bold">{product.points ?? 0}pt</p>
                  </div>
                </div>
              </div>
            </Link>
          ))}
        </div>
      )}
    </section>
  );
}
